package net.civeira.phylax.feature.observe.observedissuecomment.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.event.ObservedIssueCommentEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class ObservedIssueCommentEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<ObservedIssueCommentEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final ObservedIssueComment entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
